export function mountJoystick(el,knob,onChange){let active=null;const reset=()=>{active=null;knob.style.transform='translate(-50%,-50%)';el.classList.remove('active');onChange(0,0)};const update=e=>{const r=el.getBoundingClientRect(),radius=r.width*.34,dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,len=Math.hypot(dx,dy),scale=len>radius?radius/len:1;knob.style.transform=`translate(calc(-50% + ${dx*scale}px),calc(-50% + ${dy*scale}px))`;if(len<radius*.14)onChange(0,0);else onChange(dx*scale/radius,dy*scale/radius)};el.addEventListener('pointerdown',e=>{if(active!==null)return;e.preventDefault();active=e.pointerId;el.setPointerCapture(active);el.classList.add('active');update(e)});el.addEventListener('pointermove',e=>{if(e.pointerId===active){e.preventDefault();update(e)}});for(const type of ['pointerup','pointercancel','lostpointercapture'])el.addEventListener(type,e=>{if(e.pointerId===active)reset()});addEventListener('blur',reset);document.addEventListener('visibilitychange',()=>{if(document.hidden)reset()});return reset;}
